import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root container
  const root = new THREE.Group();

  // Apply transform
  if (config.position) root.position.set(...config.position);
  if (config.rotation) root.rotation.set(...config.rotation);
  if (config.scale) root.scale.set(...config.scale);

  // Load GLB mesh (synchronous via cached loader)
  const gltf = ctx.glbLoader(config.meshUrl);
  const mesh = gltf.scene ?? gltf;
  root.add(mesh);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Interaction handling
  const originalY = root.position.y;
  let hoverTimeline = null;

  root.userData.handlers = {};

  // Hover (rise‑in) – pointerover / pointerout
  root.userData.handlers.pointerover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(root.position, {
      y: originalY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    });
  };

  root.userData.handlers.pointerout = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(root.position, {
      y: originalY,
      duration: 0.15,
      ease: 'power3.out',
    });
  };

  // Click – emit selection event
  root.userData.handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  // Cleanup resources
  root.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
